package com.technova.model;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="usuario") public class Usuario { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="id_usuario") private Long id; private String nombre,username,password,rol; private Boolean estado; @Column(name="fecha_registro") private LocalDateTime fechaRegistro;
public Usuario(){} public Long getId(){return id;} public void setId(Long v){id=v;} public String getNombre(){return nombre;} public void setNombre(String v){nombre=v;} public String getUsername(){return username;} public void setUsername(String v){username=v;} public String getPassword(){return password;} public void setPassword(String v){password=v;} public String getRol(){return rol;} public void setRol(String v){rol=v;} public Boolean getEstado(){return estado;} public void setEstado(Boolean v){estado=v;} public LocalDateTime getFechaRegistro(){return fechaRegistro;} public void setFechaRegistro(LocalDateTime v){fechaRegistro=v;} }
